$(function(){$.validator.addMethod("havequestions",function(){var rval=!0;return 0==$(".random-q:checked").length&&(rval=!1),rval},"Wrong password"),$("#edit_form").validate({rules:{leadin:"required",questioncheck:"havequestions"},messages:{leadin:lang.enterdescription,questioncheck:lang.randomenterquestion},errorPlacement:function(error,element){"questioncheck"==element.attr("name")?error.insertAfter("#qlist-holder"):error.insertAfter(element)},invalidHandler:function(){alert(lang.validationerror)}})});